// src/components/Navbar.js
import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import logo from '../assests/logo3.png';
import { toast } from 'react-toastify';

const Navbar = ({ isAuthenticated, user, onLogout }) => {
  const [showDropdown, setShowDropdown] = useState(false);
  const location = useLocation();
  const inHomePage = location.pathname === '/';

  const toggleDropdown = () => setShowDropdown(!showDropdown);
  const handleLogout = () => {
    setShowDropdown(false);
    onLogout();
    toast.info('You have been logged out.');
  };

  return (
    <nav className="navbar navbar-expand-lg navbar-light bg-light shadow-sm sticky-top">
      <div className="container">
      <Link className="navbar-brand" to="/">
        <img src={logo} alt="Logo" height="40" />
      </Link>

        <button className="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#navbarContent" 
                aria-controls="navbarContent" aria-expanded="false" aria-label="Toggle navigation">
          <span className="navbar-toggler-icon"></span>
        </button>

        <div className="collapse navbar-collapse" id="navbarContent">
      <div className="container-fluid d-flex justify-content-between align-items-center">
        
        {/* Left Column (Logo already outside this block) */}
        <div className="flex-grow-1 d-none d-lg-block" />

        {/* Center Column (Nav Links) */}
        <ul className="navbar-nav mx-auto">
          {inHomePage ? (
            <>
              <li className="nav-item"><a className="nav-link" href="#home">Home</a></li>
              <li className="nav-item"><a className="nav-link" href="#about">About</a></li>
              <li className="nav-item"><a className="nav-link" href="#features">Features</a></li>
              <li className="nav-item"><a className="nav-link" href="#contact">Contact</a></li>
            </>
          ) : (
            <>
              <li className="nav-item"><Link className="nav-link" to="/#home">Home</Link></li>
              <li className="nav-item"><Link className="nav-link" to="/#about">About</Link></li>
              <li className="nav-item"><Link className="nav-link" to="/#features">Features</Link></li>
              <li className="nav-item"><Link className="nav-link" to="/#contact">Contact</Link></li>
            </>
          )}
        </ul>

        {/* Right Column (Sign in/Profile) */}
        <div className="d-flex align-items-center">
          {isAuthenticated ? (
            <div className="dropdown">
              <span className="nav-link dropdown-toggle text-warning" role="button" onClick={toggleDropdown}>
                {user?.name}
              </span>
              {showDropdown && (
                <ul className="dropdown-menu dropdown-menu-end show">
                  <li><button className="dropdown-item" onClick={handleLogout}>Logout</button></li>
                </ul>
              )}
            </div>
          ) : (
            <>
              <Link className="btn btn-outline-primary me-2" to="/signin">Sign In</Link>
              <Link className="btn btn-primary" to="/signup">Sign Up</Link>
            </>
          )}
        </div>
      </div>
    </div>

      </div>
    </nav>
  );
};

export default Navbar;
